// Magnetic button JS
function initMagnetic(el, radius = 80, strength = 0.3) {
  document.addEventListener('mousemove', e => {
    const r = el.getBoundingClientRect();
    const cx = r.left + r.width / 2;
    const cy = r.top + r.height / 2;
    const dx = e.clientX - cx;
    const dy = e.clientY - cy;
    const dist = Math.sqrt(dx*dx + dy*dy);
    if (dist < radius) {
      const pull = 1 - dist / radius;
      el.style.transform = `translate(${dx*pull*strength}px, ${dy*pull*strength}px)`;
    } else {
      el.style.transform = 'translate(0,0)';
    }
  });
}

// 3D tilt card JS
function initTilt(el, maxDeg = 8) {
  el.addEventListener('mousemove', e => {
    const r = el.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width - 0.5;
    const y = (e.clientY - r.top) / r.height - 0.5;
    el.style.transform = `perspective(1000px) rotateY(${x * maxDeg * 2}deg) rotateX(${-y * maxDeg * 2}deg)`;
  });
  el.addEventListener('mouseleave', () => {
    el.style.transform = 'perspective(1000px) rotateY(0) rotateX(0)';
  });
}

.card { transition: transform .1s ease; will-change: transform; }

.ticker { background: var(--accent); padding: 10px 0; overflow: hidden; white-space: nowrap; }
.ticker-inner { display: inline-block; animation: ticker 30s linear infinite; }
.ticker-inner span { padding: 0 24px; font-size: 11px; letter-spacing: 3px; }
@keyframes ticker {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); } /* duplicate content for seamless loop */
}

.mil-up { opacity: 0; transform: translateY(40px); transition: opacity .6s ease, transform .6s ease; }
.mil-left { opacity: 0; transform: translateX(-40px); transition: opacity .6s ease, transform .6s ease; }
.mil-right { opacity: 0; transform: translateX(40px); transition: opacity .6s ease, transform .6s ease; }
.mil-scale { opacity: 0; transform: scale(0.92); transition: opacity .6s ease, transform .6s cubic-bezier(.34,1.56,.64,1); }
.mil-up.visible, .mil-left.visible, .mil-right.visible, .mil-scale.visible { opacity: 1; transform: none; }

// JS — IntersectionObserver
const observer = new IntersectionObserver(entries => {
  entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); });
}, { threshold: 0.1 });
document.querySelectorAll('.mil-up, .mil-left, .mil-right, .mil-scale').forEach(el => observer.observe(el));

.section-line {
