// Stat counter JS
function animateCounter(el, target, prefix = '', suffix = '', duration = 1500) {
  let start = null;
  function step(timestamp) {
    if (!start) start = timestamp;
    const progress = Math.min((timestamp - start) / duration, 1);
    el.textContent = prefix + Math.floor(progress * target) + suffix;
    if (progress < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

// Usage
animateCounter(el, 780, '', '+'); // "780+"
animateCounter(el, 15, '€', '');  // "€15"

nav { position: fixed; top: 0; left: 0; right: 0; backdrop-filter: blur(8px); transition: transform .3s ease; }
nav.hidden { transform: translateY(-100%); }

// JS
let lastScroll = 0;
window.addEventListener('scroll', () => {
  const current = window.scrollY;
  if (current > 120 && current > lastScroll) nav.classList.add('hidden');
  else nav.classList.remove('hidden');
  lastScroll = current;
}, { passive: true });

// Hamburger toggle JS
document.querySelector('.hamburger').addEventListener('click', function() {
  this.classList.toggle('open');
  document.querySelector('.mobile-drawer').classList.toggle('open');
  document.body.style.overflow = this.classList.contains('open') ? 'hidden' : '';
});

/* CSS lines */
.hamburger span:nth-child(1) { transform: none; }
.hamburger.open span:nth-child(1) { transform: rotate(45deg) translate(6px, 6px); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: rotate(-45deg) translate(6px, -6px); }

/* Monospace type system */
:root { --font-mono: 'Courier New', Courier, monospace; }
body { font-family: var(--font-mono); }

.heading-xl { font-size: clamp(32px, 6vw, 80px); font-weight: 900; letter-spacing: 6px; text-transform: uppercase; }
.heading-sm { font-size: 12px; letter-spacing: 4px; text-transform: uppercase; color: var(--accent); }
.body-copy { font-size: 14px; letter-spacing: 2px; line-height: 1.8; color: var(--muted); }
.label { font-size: 10px; letter-spacing: 3px; text-transform: uppercase; color: var(--muted); }

.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; }
.card { background: var(--surface); border: 1px solid transparent; transition: border-color .2s, background .2s; }
.card:hover { border-color: var(--accent); }
.card.featured { grid-column: span 2; border-color: var(--accent); }

@media (max-width: 768px) {
  .grid { grid-template-columns: 1fr; }
  .card.featured { grid-column: span 1; }
}

.timeline-item { display: grid; grid-template-columns: 80px 1fr; gap: 16px; padding: 20px 0; border-top: 1px solid var(--surface); }
.timeline-year { font-size: 12px; letter-spacing: 2px; color: var(--accent); }
.timeline-title { font-size: 14px; letter-spacing: 2px; color: var(--cream); font-weight: 700; margin-bottom: 8px; }
.timeline-body { font-size: 13px; color: var(--muted); line-height: 1.8; }
